package com.cybershield.controller; import com.cybershield.repository.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import java.nio.charset.StandardCharsets;
@RestController @RequestMapping("/api/reports") public class ReportController { final IncidentRepository r; public ReportController(IncidentRepository r){this.r=r;} @GetMapping(value="/incidents.csv",produces="text/csv") @PreAuthorize("hasAnyRole('ADMIN','ANALYST')") ResponseEntity<byte[]> csv(){StringBuilder s=new StringBuilder("ID,Title,Type,Severity,Priority,Status,Detected At\n");r.findAll().forEach(i->s.append(i.getId()).append(',').append(q(i.getTitle())).append(',').append(q(i.getIncidentType())).append(',').append(q(i.getSeverity())).append(',').append(q(i.getPriority())).append(',').append(q(i.getStatus())).append(',').append(q(String.valueOf(i.getDetectedAt()))).append('\n'));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=cybershield-incidents.csv").body(s.toString().getBytes(StandardCharsets.UTF_8));} String q(String x){return "\""+(x==null?"":x.replace("\"","\"\""))+"\"";} }
